<?php
require_once 'config.php';requirePost();$user=requireRole('admin','supervisor','expert');if($user['role']!=='expert'&&!hasPermission('can_chat'))jsonResponse(['success'=>false,'message'=>'دسترسی چت غیرفعال است.'],403);$id=postInt('conversation_id');$title=normalizeText((string)($_POST['title']??''),100);if($id<1||$title==='')jsonResponse(['success'=>false,'message'=>'نام گروه را وارد کنید.'],400);$st=$pdo->prepare("SELECT id FROM chat_conversations WHERE id=? AND type='group' AND created_by=? AND created_by_role=?");$st->execute([$id,$user['username'],$user['role']]);if(!$st->fetch())jsonResponse(['success'=>false,'message'=>'فقط سازنده گروه می‌تواند نام آن را تغییر دهد.'],403);$st=$pdo->prepare("UPDATE chat_conversations SET title=? WHERE id=?");$st->execute([$title,$id]);jsonResponse(['success'=>true,'message'=>'نام گروه تغییر کرد.']);
